```javascript
const helmet = require('helmet');
const cors = require('cors');

// Secure HTTP headers
app.use(helmet({
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// Configure CORS (be specific about origins)
