      AWS_SECRET_ACCESS_KEY: this.maskSecret(this.secrets.AWS_SECRET_ACCESS_KEY),
      STRIPE_SECRET_KEY: this.maskSecret(this.secrets.STRIPE_SECRET_KEY),
      DATABASE_URL: this.maskDatabaseUrl(this.secrets.DATABASE_URL),
    };

    // ✅ Log info (without sensitive data)
    console.log(`Loaded ${Object.keys(this.secrets).length} secrets from environment`);
    return this.secrets;
  },

  maskSecret(secret, visibleChars = 4) {
    if (!secret || secret.length <= visibleChars) return '****';
    const total = secret.length;
    const visibleStart = Math.floor(visibleChars / 2);
    const visibleEnd = visibleChars - visibleStart;
    return `${secret.substring(0, visibleStart)}${'*'.repeat(total - visibleChars)}${secret.substring(total - visibleEnd)}`;
  },

  maskDatabaseUrl(url) {
    try {
      const urlObj = new URL(url);
      const password = this.maskSecret(urlObj.password || 'secret');
      return `${urlObj.protocol}//${urlObj.username}:${password}@${urlObj.host}${urlObj.pathname}`;
    } catch {
      return this.maskSecret(url);
    }
  },

  get secret(name) {
    return this.secrets[name];
  }
};

