### SOLUTION 2: AWS Secrets Manager (Production)

```javascript
// app.js - AWS Secrets Manager integration
const AWS = require('aws-sdk');
const { promisify } = require('util');

// Configure AWS
AWS.config.update({
  region: process.env.AWS_REGION || 'us-east-1'
});

const getSecretValue = promisify(AWS.SecretsManager().getSecretValue.bind(AWS.SecretsManager()));

const loadSecretsFromAWS = async (secretName) => {
  try {
    const data = await getSecretValue({ SecretId: secretName });
    return JSON.parse(data.SecretString);
  } catch (err) {
    console.error('Error loading secret from AWS:', err);
    throw new Error('Failed to load secrets');
  }
};

// Cache secrets
let cachedSecrets = null;

const getSecrets = async () => {
  if (!cachedSecrets) {
    cachedSecrets = await loadSecretsFromAWS(process.env.SECRET_MANAGER_NAME);
  }
  return cachedSecrets;
};

// Usage - lazy load on first use
app.get('/users', async (req, res) => {
  const secrets = await getSecrets();
  // Access: secrets.JWT_SECRET, secrets.DATABASE_URL
  res.json({ message: 'Protected route' });
});
