### secure-app.js (Full Implementation):
```javascript
/**
 * Secure Application with proper secrets management
 * Requires: dotenv, helmet, cors, express-validator, express-rate-limit
 */

require('dotenv').config();
require('module-alias/register');

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { validationResult } = require('express-validator');
const { body, query } = require('express-validator');

const app = express();

// ============================================
// 1. SECURITY MIDDLEWARE
// ============================================
app.use(helmet({
  contentSecurityPolicy: process.env.NODE_ENV === 'production' ? {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'"],
      styleSrc: ["'self' 'unsafe-inline'"],
      imgSrc: ["'self' data:", 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"]
    }
  } : false
}));

app.use(cors({
  origin: (origin, callback) => {
    const allowedOrigins = process.env.ALLOWED_ORIGINS?.split(',') || [];
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('CORS Not Allowed'));
    }
  },
  credentials: true
}));

// ============================================
// 2. RATE LIMITING
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  standardHeaders: true,
  legacyHeaders: false,
  message: { error: 'Too many requests. Try again later.' }
});

app.use('/api/', limiter);

// ============================================
// 3. SECRET VALIDATION
// ============================================
function validateRequiredSecrets() {
  const required = ['JWT_SECRET', 'ALLOWED_ORIGINS'];
  const missing = required.filter(key => !process.env[key]);

  if (missing.length > 0) {
    console.error('❌ Missing required secrets:', missing.join(', '));
    throw new Error(`Missing required environment variables: ${missing.join(', ')}`);
  }

  console.log('✅ Required secrets validated');
}

function validateSecretStrength() {
  const jwtSecret = process.env.JWT_SECRET;

  // Minimum 32 characters
  if (jwtSecret.length < 32) {
    console.error('⚠️ JWT_SECRET is too short. Minimum 32 characters recommended.');
  }

  // Check for common patterns
  const commonPatterns = ['password', 'secret', 'key', 'token'];
  const hasWeakPattern = commonPatterns.some(pattern => 
    jwtSecret.toLowerCase().includes(pattern)
  );

  if (hasWeakPattern) {
    console.error('⚠️ JWT_SECRET contains weak naming patterns');
  }
}

// ============================================
// 4. SECRET LOADING
// ============================================
const getSecrets = () => {
  // In production, load from secrets manager
  // For now, use environment variables with validation

  validateSecretStrength();

  return {
    jwt: {
      secret: process.env.JWT_SECRET,
      algorithm: process.env.JWT_ALGORITHM || 'HS256',
      expiry: process.env.JWT_EXPIRY || '24h'
    },
    cors: {
      allowedOrigins: process.env.ALLOWED_ORIGINS.split(',').map(o => o.trim())
    },
    logging: process.env.LOG_LEVEL || 'info'
  };
};

// Cache secrets
let cachedSecrets = null;

const loadSecrets = () => {
  if (!cachedSecrets) {
    cachedSecrets = getSecrets();
  }
  return cachedSecrets;
};

// ============================================
// 5. INPUT VALIDATION
// ============================================
const validate = (schema) => {
  return [
    schema,
    (req, res, next) => {
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        return res.status(400).json({ 
          success: false, 
          errors: errors.array() 
        });
      }
      next();
    }
  ];
};

// ============================================
// 6. ROUTES
// ============================================
// Health check - explicit auth required
app.get(
  '/health',
  validate([
    query('token')
      .notEmpty()
      .withMessage('Token is required')
      .isString()
      .trim()
      .escape()
  ]),
  (req, res) => {
    res.json({
      status: 'ok',
      timestamp: new Date().toISOString(),
      version: process.env.APP_VERSION || '1.0.0',
      environment: process.env.NODE_ENV
    });
  }
);

// User endpoint - protected
app.get('/users', (req, res) => {
  // In production: query database with authenticated user
  if (process.env.NODE_ENV === 'development') {
    return res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' }
    ]);
  }

  res.status(503).json({ 
    success: false, 
    error: 'Service unavailable in production' 
  });
});

// ============================================
// 7. ERROR HANDLING
// ============================================
app.use((err, req, res, next) => {
  const secrets = loadSecrets();

  console.error('Error:', {
    message: err.message,
    path: req.path,
    method: req.method,
    ip: req.ip,
    ...(process.env.NODE_ENV === 'development' && {
      stack: err.stack
    })
  });

  res.status(err.statusCode || 500).json({
    success: false,
    error: process.env.NODE_ENV === 'development' 
      ? err.message 
      : 'Internal server error'
  });
});

// ============================================
// 8. STARTUP
// ============================================
const start = async () => {
  try {
    validateRequiredSecrets();
    const secrets = loadSecrets();

    console.log('🔐 Secrets loaded successfully');

    const server = await new Promise((resolve, reject) => {
      app.listen(3000, '0.0.0.0', () => resolve(app.listen));
    });

    console.log(`🚀 Server running on ${process.env.NODE_ENV} mode`);
    console.log(`📡 Listening on port 3000`);
  } catch (error) {
    console.error('❌ Failed to start server:', error.message);
    process.exit(1);
  }
};

// ============================================
// 9. GRACEFUL SHUTDOWN
// ============================================
process.on('SIGTERM', async () => {
  console.log('SIGTERM received, shutting down gracefully...');
  process.exit(0);
});

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection:', reason);
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  process.exit(1);
});

// Start the application
start();

// Export for testing
module.exports = { app, getSecrets, loadSecrets };
```

