```javascript
// utils/validateEnv.js
module.exports = function validateEnv(options) {
  const { 
    required, 
    optional = [], 
    shouldNotStartWith = ['CANARY_']
  } = options;

  const errors = [];
  const warnings = [];
  const validEnvVars = {};

  // Check all environment variables
  Object.keys(process.env).forEach(key => {
    // Check if variable should not start with forbidden prefixes
    shouldNotStartWith.forEach(forbiddenPrefix => {
      if (key.startsWith(forbiddenPrefix)) {
        warnings.push(
          `${key} appears to be a test/canary value in production`
        );
      }
    });

    validEnvVars[key] = process.env[key];
  });

  // Check required variables
  required.forEach(key => {
    if (!process.env[key]) {
      errors.push(`Missing required environment variable: ${key}`);
    }
  });

  // Optional validation - check patterns
  optional.forEach(opt => {
    const { key, validator, errorMessage } = opt;
    const value = process.env[key];

    if (value && validator && !validator(value)) {
      errors.push(errorMessage || `Invalid value for ${key}`);
    }
  });

  // Print results
  if (errors.length > 0) {
    console.error('❌ Environment validation failed:');
    errors.forEach(err => console.error(`  - ${err}`));
    throw new Error('Environment configuration is invalid');
  }

  if (warnings.length > 0) {
    console.warn('⚠️  Environment warnings:');
    warnings.forEach(warn => console.warn(`  - ${warn}`));
  }

  console.log('✅ Environment validation passed');

  return validEnvVars;
};

