# Security Review: app.js

## Executive Summary
This is a extremely simple Express.js application with minimal functionality, but it still has several security vulnerabilities that should be addressed.

## Issues Found

### 🔴 CRITICAL VULNERABILITIES

#### 1. SQL Injection Attack Vector (Possible Future Impact)
**Location**: The `/users` endpoint with potential future database integration.

**Severity**: CRITICAL

**Description**: While there's no SQL in the code yet, the endpoint returns user data that could later be connected to a database. If database queries are added without proper parameterization, SQL injection attacks will be possible.

**Current State**: Low Risk (no database yet)

**Risk Level**: Shows lack of security-conscious design from the start.

**Recommendation**:
```javascript
// Good practice - API design for security from the start
app.get('/users', async (req, res) => {
  try {
    // If you later add a database:
    // Use parameterized queries (pg/sequelize/prisma handle this automatically)

    const db = require('./db'); // Your database module

    // Secure: Using parameterized queries via ORM
    const users = await db.user.findAll({
      attributes: ['id', 'name', 'email'], // Only return necessary fields
      where: {
        // Add authorization checks here
      }
    });

    res.json(users);
  } catch (error) {
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

---

### 🟡 HIGH SEVERITY VULNERABILITIES

#### 2. Missing Authentication
**Location**: All endpoints (`/health`, `/users`)

**Severity**: HIGH

**Description**: No authentication or authorization mechanism is implemented. Any client can access all endpoints without any verification.

**Attack Scenario**:
- An attacker can access `/health` endpoint
- An attacker can read all user data without permission
- No protection against API abuse or DoS attacks

**Recommendation - Option 1 (Quick Fix for Internal API)**:
```javascript
const helmet = require('helmet');
const expressRateLimit = require('express-rate-limit');
const rateLimit = expressRateLimit({
  windowMs: 15 * 60 * 1000, // 15 minute window
  max: 100 // Limit each IP to 100 requests per windowMs
});

// Apply security middleware globally
app.use(helmet());              // Security headers
app.use(rateLimit);             // Rate limiting
app.use(express.json());        // Parse JSON with body size limit

// Add authentication middleware for protected routes
function requireAuth(req, res, next) {
  // Basic implementation - use JWT or other proper auth
  const authHeader = req.headers['authorization'];
  if (!authHeader) {
    return res.status(401).json({ error: 'Authentication required' });
  }
  // Validate the token and attach user info to req
  next();
}

// Apply to authenticated routes
app.get('/health', (req, res) => {
  // This can remain public
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', requireAuth, async (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation - Option 2 (Proper Auth)**:
```javascript
const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_THIS_IN_PRODUCTION';
const SECRET_KEY = process.env.JWT_SECRET;

function generateToken(userId, role) {
  return jwt.sign(
    { userId, role },
    SECRET_KEY,
    { expiresIn: '24h' }
  );
}

function requireAuth(req, res, next) {
  const authHeader = req.headers['authorization'];
  if (!authHeader?.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'Missing or invalid token' });
  }

  const token = authHeader.substring(7);
  try {
    const decoded = jwt.verify(token, SECRET_KEY);
    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid or expired token' });
  }
}

app.get('/login', async (req, res) => {
  // Validate credentials and return token
  const user = await authenticateUser(req.body.username, req.body.password);
  const token = generateToken(user.id, user.role);
  res.json({ token });
});

app.get('/users', requireAuth, (req, res) => {
  res.json([/* user data with role-based access */]);
});
```

#### 3. Missing Request Validation (Input Validation)
**Location**: No validation on any endpoint

**Severity**: HIGH

**Description**: No input validation is implemented. This allows:
- Malformed requests to reach the application
- Potential memory exhaustion attacks
- No validation of data format

**Vulnerable Endpoints**: `/health`, `/users`

**Recommendation**:
```javascript
const Joi = require('joi'); // Or use zod, class-validator, or express-validator

// Define validation schemas
const userSchema = Joi.object({
  id: Joi.number().integer().optional(),
  name: Joi.string().min(1).max(100).required(),
  email: Joi.string().email().required()
});

// Validation middleware using express-validator
const validate = (schema) => {
  return (req, res, next) => {
    const { error } = schema.validate(req.body, {
      abortEarly: false,
      stripUnknown: true // Remove unknown fields
    });

    if (error) {
      const details = error.details.map(d => ({
        field: d.path.join('.'),
        message: d.message
      }));
      return res.status(400).json({ error: 'Validation failed', details });
    }

    next();
  };
};

// Apply validation
app.post('/users', requireAuth, validate(userSchema), (req, res) => {
  // Validation passed, safe to access req.body
  res.json({ id: generateId(), ...req.body });
});

// Query parameter validation
app.get('/users/:id', requireAuth, (req, res, next) => {
  if (!/^\d+$/.test(req.params.id)) {
    return res.status(400).json({ error: 'Invalid user ID' });
  }
  next();
});
```

---

### 🟠 MEDIUM SEVERITY VULNERABILITIES

#### 4. Missing Rate Limiting
**Location**: All endpoints

**Severity**: MEDIUM

**Description**: No rate limiting means the application can be easily abused for:
- DoS attacks
- Data scraping
- API abuse

**Recommendation**:
```javascript
const rateLimit = require('express-rate-limit');

// Apply global limiter
const globalLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: ' Too many requests, please try again later',
  standardHeaders: true,
  legacyHeaders: false,
});

// More specific limiters for sensitive endpoints
const authLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 10, // 10 attempts per hour per IP
  message: 'Too many authentication attempts',
  skipSuccessfulRequests: true
});

app.use(globalLimiter);
app.post('/login', authLimiter, authenticateUser);
```

#### 5. Missing Security Headers (Helmet)
**Location**: No security headers applied

**Severity**: MEDIUM

**Description**: Missing security headers leave the application vulnerable to:
- Clickjacking
- XSS attacks
- Unknown vulnerabilities

**Recommendation**:
```javascript
const helmet = require('helmet');

// Apply secure headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'"], // Add specific script sources
      connectSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-site" },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  }
}));
```

#### 6. Missing HTTPS Check
**Location**: Production deployment concern

**Severity**: MEDIUM

**Description**: Application will accept both HTTP and HTTPS, which allows man-in-the-middle attacks.

**Recommendation**:
```javascript
const https = require('https');
