### 8. No HTTPS/TLS Implementation
**Severity:** CRITICAL
**OWASP:** A01:2021

**Problem:** Application runs over HTTP, exposing all traffic in clear text.

**Risk:** Credentials, session tokens, and sensitive data can be intercepted.

**Recommendation: Use HTTPS with valid certificates**

```javascript
const fs = require('fs');
const https = require('https');

// Load SSL certificates
const sslOptions = {
  key: fs.readFileSync(process.env.SSL_KEY_PATH),
  cert: fs.readFileSync(process.env.SSL_CERT_PATH),
  ca: fs.readFileSync(process.env.SSL_CA_PATH),
};

// Redirect HTTP to HTTPS
const redirectToHTTPS = (req, res, next) => {
  if (process.env.NODE_ENV === 'production' && !req.secure) {
    return res.redirect(301, 'https://' + req.headers.host + req.url);
  }
  next();
};

// Add HTTPS middleware
app.use(redirectToHTTPS);

// or create HTTPS server
https.createServer(sslOptions, app).listen(PORT, () => {
  console.log(`Secure server running on port ${PORT}`);
});

// or combine HTTP and HTTPS
const http = require('http');
http.createServer((req, res) => {
  // Handle custom internal proxy headers
  const protocol = req.headers['x-forwarded-proto'] || 'http';
  const secure = protocol === 'https';

  if (secure) {
    console.log('HTTPS request received from:', req.ip);
    next(req, res);
  } else {
    res.writeHead(301, {
      Location: `https://${req.headers.host}${req.url}`,
    }).end();
  }
});
```

