### 10. No Logging and Monitoring
**Severity:** MEDIUM
**OWASP:** N/A

**Problem:** No request logging or security event logging.

**Risk:** Cannot detect attacks or debug security issues.

**Recommendation: Implement comprehensive logging**

```javascript
const morgan = require('morgan');
const fs = require('fs');
const path = require('path');

// Log file
const accessLogStream = fs.createWriteStream(
  path.join(__dirname, 'access.log'),
  { flags: 'a' }
);

// Combine with security events
const securityLimiter = rateLimit({
  // ... configuration
  handler: (req, res) => {
    // Log security events
    console.error({
      level: 'security',
      message: 'Rate limit exceeded',
      ip: req.ip,
      endpoint: req.path,
      userAgent: req.get('User-Agent'),
      timestamp: new Date().toISOString(),
    });

    fs.appendFileSync('security.log', JSON.stringify({
      level: 'security',
      event: 'rate_limit_exceeded',
      ip: req.ip,
      path: req.path,
      userAgent: req.get('User-Agent'),
      timestamp: new Date().toISOString(),
    }) + '\n');
  },
});

// Use morgan in production
if (process.env.NODE_ENV === 'production') {
  app.use(morgan('combined', { stream: accessLogStream }));
} else {
  app.use(morgan('dev'));
}

// Request ID for tracking
app.use((req, res, next) => {
  req.id = crypto.randomUUID();
  res.setHeader('X-Request-ID', req.id);
  next();
});
```

