### Option 3: AWS Secrets Manager (AWS Production)

#### 1. Install AWS SDK
```bash
npm install @aws-sdk/client-secrets-manager
```

#### 2. Create Secrets Manager in AWS Console
- Name: `prod/my-app/secrets`
- Secret format: JSON
  ```json
  {
    "DATABASE_URL": "postgres://dbuser:db_pass@host:5432/db",
    "JWT_SECRET": "very_long_random_secret_here"
  }
  ```

#### 3. Load secrets from AWS
```javascript
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');
const AWS = require('aws-sdk');

// Configure AWS SDK with region
AWS.config.update({
  region: process.env.AWS_REGION || 'us-east-1',
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  }
});

// Create client
const secretsClient = new SecretsManagerClient();

/**
 * Get secret from AWS Secrets Manager
 * @param {string} secretName - The name of the secret
 * @returns {Promise<string>} - Secret value as JSON string
 */
async function getSecret(secretName) {
  try {
    const command = new GetSecretValueCommand({ SecretId: secretName });
    const response = await secretsClient.send(command);

    return secretName.endsWith('json')
      ? JSON.parse(response.SecretString)
      : response.SecretString;

  } catch (error) {
    if (error.name === 'ResourceNotFoundException') {
      throw new Error(`Secret ${secretName} not found in AWS Secrets Manager`);
    }
    console.error('Failed to fetch secret:', error);
    throw error;
  }
}

// Usage example
(async () => {
  try {
    const secrets = await getSecret('prod/my-app/secrets');

    // Decrypt individually
    const dbUrl = secrets.DATABASE_URL;
    const jwtSecret = secrets.JWT_SECRET;

    console.log('Successfully loaded secrets from AWS');
    // Use secrets here
  } catch (error) {
    console.error('Failed to load secrets:', error);
    process.exit(1);
  }
})();
```

##### AWS Secrets Manager with Connection Pool
```javascript
const { Pool } = require('pg');

// Load credentials from AWS Secrets Manager at startup
async function createDBPool() {
  const secrets = await getSecret('prod/my-app/database-credentials');

  return new Pool({
    host: secrets.host,
    port: secrets.port,
    database: secrets.dbname,
    user: secrets.username,
    password: secrets.password,
    ssl: {
      rejectUnauthorized: false, // Required for production RDS
    },
  });
}

// Use the pool in your application
const db = await createDBPool();
```

