### Option 4: HashiCorp Vault (Enterprise Secret Management)

#### 1. Install Vault client for Node.js
```bash
npm install vault
```

#### 2. Configure Vault connection
```javascript
const Vault = require('vault');

const vaultConfig = {
  approle: {
    roleId: process.env.VAULT_ROLE_ID,
    secretId: process.env.VAULT_SECRET_ID,
  },
};

const vault = new Vault(vaultConfig);

/**
 * Get secret from Vault
 * @param {string} path - Secret path (e.g., 'secret/data/myapp')
 * @param {string} key - Secret key within the path
 * @returns {Promise<string>}
 */
async function getVaultSecret(path, key) {
  try {
    await vault.login();

    const secret = await vault.read(path);
    return secret.data.data[key];
  } catch (error) {
    console.error('Failed to fetch secret from Vault:', error);
    throw error;
  }
}

// Usage
(async () => {
  const jwtSecret = await getVaultSecret('secret/data/myapp', 'jwt-secret');
  const dbPassword = await getVaultSecret('secret/data/myapp', 'db-password');

  console.log('Loaded secrets from Vault');
})();
```

