// ./config/secrets-loader.js
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

// Encrypt/Decrypt secret files
class SecretManager {
  constructor() {
    this.env = process.env.NODE_ENV || 'development';
    this.secretsFile = path.join(process.cwd(), `.env.${this.env}`);
    this.key = process.env.ENCRYPTION_KEY || this.generateKey();
  }

  generateKey() {
    // Generate 256-bit key
    return crypto.randomBytes(32).toString('hex');
  }

  encrypt(text) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-cbc', Buffer.from(this.key), iv);
    let encrypted = cipher.update(text);
    encrypted = Buffer.concat([encrypted, cipher.final()]);
    return iv.toString('hex') + ':' + encrypted.toString('hex');
  }

  decrypt(text) {
    const parts = text.split(':');
    const iv = Buffer.from(parts[0], 'hex');
    const encryptedText = Buffer.from(parts[1], 'hex');
    const decipher = crypto.createDecipheriv('aes-256-cbc', Buffer.from(this.key), iv);
    let decrypted = decipher.update(encryptedText);
    decrypted = Buffer.concat([decrypted, decipher.final()]);
    return decrypted.toString();
  }

  loadSecrets() {
    if (!fs.existsSync(this.secretsFile)) {
      console.warn(`No secrets file found for environment: ${this.env}`);
      return {};
    }

    const secretsContent = fs.readFileSync(this.secretsFile, 'utf8');
    const secrets = {};

    secretsContent.split('\n').forEach(line => {
      if (line.startsWith('#') || !line.trim()) return;

      const [key, value] = line.split('=');
      // Example: PROTECTED_SECRET=ENC:...
      if (value.startsWith('ENC:')) {
        const decrypted = this.decrypt(value.replace('ENC:', ''));
        secrets[key] = decrypted;
      } else {
        secrets[key] = value;
      }
    });

    return secrets;
  }

  writeSecrets(secrets) {
    const content = Object.entries(secrets)
      .map(([key, value]) => {
        if (key.includes('SECRET') || key.includes('KEY')) {
          // Example: PROTECTED_SECRET=ENC:<encrypted_value>
          return `${key}=ENC:${this.encrypt(value)}`;
        }
        return `${key}=${value}`;
      })
      .join('\n');

    fs.writeFileSync(this.secretsFile, content, 'utf8');
  }
}

module.exports = SecretManager;
