# Security Review: app.js

## Executive Summary
The current `app.js` is a minimal Express.js application with basic health check and user endpoints. However, it has **multiple critical security vulnerabilities** across OWASP Top 10 categories.

**Severity Assessment:** 🔴 **CRITICAL**
- **Timeline:** Would be exploited within minutes of deployment
- **Risk Level:** High/Extreme
- **Impact:** Information disclosure, potential DoS, server compromise

---

## Critical Vulnerabilities

### 1. 🔴 Authentication & Authorization (A01)
**Severity:** CRITICAL | **Category:** OWASP A01:2021 – Broken Access Control

**Issue:**
- No authentication mechanism whatsoever
- Public exposure of sensitive user data (emails, names, IDs)
- No authorization checks for any endpoints

**Evidence:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },  // ← Sensitive data exposed
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});
```

**Recommendation:**
Implement authentication with JWT tokens and role-based access control:

```javascript
const jwt = require('jsonwebtoken');
const bcrypt = require('bcrypt');
const User = require('./models/user'); // Example schema

// Secret key configuration - should be in environment variables
const JWT_SECRET = process.env.JWT_SECRET || 'CHANGE_THIS_SECRET';
const JWT_EXPIRE = '24h';

// Login endpoint
app.post('/api/login', async (req, res) => {
  try {
    const { email, password } = req.body;

    if (!email || !password) {
      return res.status(400).json({ error: 'Email and password required' });
    }

    const user = await User.findOne({ email });
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const isValid = await bcrypt.compare(password, user.passwordHash);
    if (!isValid) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    const token = jwt.sign(
      { userId: user.id, email: user.email, role: user.role },
      JWT_SECRET,
      { expiresIn: JWT_EXPIRE }
    );

    res.json({
      token,
      user: {
        id: user.id,
        email: user.email,
        name: user.name,
        role: user.role
      }
    });
  } catch (error) {
    console.error('Login error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Protected route example
app.get('/api/users', authenticateToken, async (req, res) => {
  try {
    // Only return users the authenticated user has access to
    const users = await User.find(
      { _id: { $in: req.user.accessibleUserIds } },
      ['id', 'name', 'email', 'role'] // Project only necessary fields
    );
    res.json(users);
  } catch (error) {
    console.error('Fetch users error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});

// Middleware to validate JWT
function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, JWT_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// Admin/Protected route example
app.get('/api/admin/users', authenticateToken, checkRole('admin'), async (req, res) => {
  const users = await User.find();
  res.json(users);
});

// Role checking middleware
function checkRole(requiredRole) {
  return (req, res, next) => {
    if (req.user && req.user.role === requiredRole) {
      next();
      return;
    }
    res.status(403).json({ error: 'Access denied. Insufficient permissions.' });
  };
}
```

---

### 2. 🔴 SQL Injection (A03)
**Severity:** CRITICAL | **Category:** OWASP A03:2021 – Injection

**Issue:**
- If DB operations were added, the application uses raw database queries without parameterization
- User input from `req.body` or `req.params` is directly concatenated

**Vulnerable Pattern:**
```javascript
// ❌ VULNERABLE - DO NOT USE
db.collection('users').find({ email: req.body.email })
// OR
db.query(`SELECT * FROM users WHERE email = '${req.body.email}'`)
// OR
db.collection('users').find({ email: req.query.email })
```

**Recommendation:**
Use parameterized queries with ORM or prepared statements:

```javascript
// Using Mongoose/Express examples
const User = require('./models/user');

// ✅ SECURE - Parameterized with Mongoose
app.get('/api/users/:email', authenticateToken, async (req, res) => {
  try {
    // Mongoose automatically parameterizes queries
    const user = await User.findOne({ email: new RegExp(req.params.email, 'i') });
    // OR use $or for partial matching:
    // const users = await User.find({
    //   email: { $regex: req.params.email, $options: 'i' },
    //   _id: { $in: req.user.accessibleUserIds }
    // });

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }
    res.json(user);
  } catch (error) {
    res.status(400).json({ error: 'Invalid user email' });
  }
});

// Using raw MongoDB with parameterization:
const mongodb = require('mongodb');
const client = new mongodb.MongoClient(process.env.MONGODB_URI);

// ✅ SECURE - Parameterized queries
app.get('/api/users/by-email', authenticateToken, async (req, res) => {
  try {
    const db = client.db();
    // Only use regex for partial matching, which is safer
    const collection = db.collection('users');
    const users = await collection.find({
      email: { $regex: req.query.email || '', $options: 'i' },
      _id: { $in: req.user.accessibleUserIds }
    }).toArray();
    res.json(users);
  } catch (error) {
    res.status(400).json({ error: 'Invalid email parameter' });
  }
});
```

```javascript
// Using PostgreSQL with parameterized queries:
const { Pool } = require('pg');
const pool = new Pool({ connectionString: process.env.DATABASE_URL });

app.get('/api/users', authenticateToken, async (req, res) => {
  try {
    const { rows } = await pool.query(
      'SELECT id, name, email FROM users WHERE id = ANY($1)',
      [req.user.accessibleUserIds]
    );
    res.json(rows);
  } catch (error) {
    console.error('Query error:', error);
    res.status(500).json({ error: 'Database error' });
  }
});

// Example input validation
function validateEmail(email) {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email) && email.length <= 254;
}

function validatePagination(params) {
  return {
    limit: Math.min(Math.max(parseInt(params.limit) || 10, 1), 100),
    page: Math.max(parseInt(params.page) || 1, 1)
  };
}
```

---

### 3. 🔴 Path Traversal (A05)
**Severity:** CRITICAL | **Category:** OWASP A05:2021 – Security Misconfiguration

**Issue:**
- If file serving endpoints were added, no path validation present
- Could allow access to system files via directory traversal characters (`../`)

**Recommendation:**
Validate and sanitize file paths:

```javascript
const path = require('path');
const fs = require('fs');

// ✅ SECURE - Path validation
app.get('/api/files/:filename', authenticateToken, async (req, res) => {
  try {
    const requestedFileName = req.params.filename;

    // Block path traversal attempts
    if (requestedFileName.includes('..') || requestedFileName.includes('/')) {
      return res.status(400).json({ error: 'Invalid filename' });
    }

    // Allow only allowed extensions
    const allowedExtensions = ['.txt', '.js', '.json'];
    const ext = path.extname(requestedFileName).toLowerCase();
    if (!allowedExtensions.includes(ext)) {
      return res.status(400).json({ error: 'File type not allowed' });
    }

    // Normalize path to prevent directory traversal
    const safePath = path.normalize(path.join(__dirname, 'uploads', requestedFileName));

    // ❌ CRITICAL: MUST ALSO VERIFY sanitized path still resolves to allowed directory
    if (!safePath.startsWith(path.join(__dirname, 'uploads'))) {
      return res.status(403).json({ error: 'Access denied' });
    }

    if (!fs.existsSync(safePath)) {
      return res.status(404).json({ error: 'File not found' });
    }

    res.sendFile(safePath, {
      maxAge: '3600s',
      lastModified: true
    });
  } catch (error) {
    console.error('File access error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
