### 4. 🟠 Insecure Deserialization (A08)
**Severity:** HIGH | **Category:** OWASP A08:2021 – Software and Data Integrity Failures

**Issue:**
- No validation of request data structure or types
- JSON payloads processed without schema validation

**Vulnerable Pattern:**
```javascript
// ❌ VULNERABLE
app.post('/api/create-user', async (req, res) => {
  const user = req.body;  // No validation
  const newUser = await User.create(user);  // Could set unauthorized fields
});
```

**Recommendation:**
Implement schema validation:

```javascript
const Joi = require('joi');

// Using Joi for schema validation
const userSchema = Joi.object({
  name: Joi.string().min(2).max(50).required(),
  email: Joi.string().email().required(),
  password: Joi.string().min(8).pattern(
    /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&])[A-Za-z\d@$!%*?&]/
  ).required().messages({
    'string.pattern.base': 'Password must have uppercase, lowercase, number, and special character'
  }),
  age: Joi.number().integer().min(18).max(120),
  role: Joi.string().valid('user', 'admin').allow(null)
});

// ✅ SECURE - With validation
app.post('/api/create-user', authenticateToken, checkRole('admin'), async (req, res) => {
  try {
    // Validate request body
    const { error, value } = userSchema.validate(req.body);

    if (error) {
      return res.status(400).json({
        error: 'Validation failed',
        details: error.details.map(d => d.message)
      });
    }

    const newUser = await User.create({
      name: value.name,
      email: value.email.toLowerCase().trim(),
      passwordHash: await bcrypt.hash(value.password, 12),
      age: value.age || null,
      role: value.role || 'user'
    });

    res.status(201).json({
      id: newUser.id,
      name: newUser.name,
      email: newUser.email,
      role: newUser.role
    });
  } catch (error) {
    console.error('Create user error:', error);

    // Handle duplicate email error
    if (error.code === 11000) {
      return res.status(409).json({ error: 'Email already registered' });
    }

    res.status(500).json({ error: 'Internal server error' });
  }
});

// Validate API responses
function sanitizeUser(user) {
  return {
    id: user.id,
    name: user.name,
    email: user.email,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt
  };
}

app.get('/api/users/:userId', authenticateToken, async (req, res) => {
  try {
    const user = await User.findById(req.params.userId);

    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    // Verify user has access to another user's data
    if (!req.user.accessibleUserIds.includes(user.id)) {
      return res.status(403).json({ error: 'Access denied' });
    }

    // Never return sensitive fields
    res.json(sanitizeUser(user));
  } catch (error) {
    console.error('Fetch user error:', error);
    res.status(500).json({ error: 'Internal server error' });
  }
});
```

