### 6. 🟡 Security Headers Missing (A05)
**Severity:** HIGH | **Category:** OWASP A05:2021 – Security Misconfiguration

**Issue:**
- No security headers configured
- Missing CSRF protection, X-Frame-Options, CSP, etc.

**Recommendation:**
Add security middleware:

```javascript
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');

// ✅ SECURE - Apply security headers
app.use(helmet({
  contentSecurityPolicy: false, // Can be enabled with proper configuration
  frameguard: { action: 'deny' }, // Prevent clickjacking
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }
}));

// ✅ SECURE - CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || [
    'https://yourdomain.com'
  ],
  credentials: true,
  exposedHeaders: ['X-Total-Count'], // For pagination totals
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
};
app.use(cors(corsOptions));

// ✅ SECURE - Rate limiting
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  standardHeaders: true,
  legacyHeaders: false,
  message: {
    error: 'Too many requests, please try again later',
    retryAfter: 15 * 60
  },
  handler: (req, res) => {
    res.setHeader('X-RateLimit-Limit', 100);
    res.setHeader('X-RateLimit-Remaining', 0);
    res.status(429).json(res.locals.rateLimit);
  }
});

// Apply different limits to different routes
app.use('/api', apiLimiter);

// ✅ Secure default headers can be customized
app.use((req, res, next) => {
  res.setHeader('X-Content-Type-Options', 'nosniff');
  res.setHeader('X-Permitted-Cross-Domain-Policies', 'all');
  res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
  next();
});

// Input validation middleware
function validateRequestBody(req, res, next) {
  if (!req.body || typeof req.body !== 'object') {
    return res.status(400).json({ error: 'Invalid request body' });
  }
  next();
}
```

