let failedAttempts = new Map();
const MAX_ATTEMPTS = 5;
const BLOCK_DURATION = 15 * 60 * 1000; // 15 minutes

function checkAccountLockout(req, res, next) {
  const identifier = req.body.email || req.body.username || req.ip;

  if (failedAttempts.has(identifier)) {
    const attempt = failedAttempts.get(identifier);
    if (attempt.count >= MAX_ATTEMPTS && Date.now() < attempt.until) {
      const timeRemaining = Math.ceil((attempt.until - Date.now()) / 1000 / 60);
      logger.warn(`Account ${identifier} locked. Time remaining: ${timeRemaining} minutes`);
      return res.status(429).json({
        error: 'Too many failed attempts. Please try again later.'
      });
    } else if (Date.now() > attempt.until) {
      failedAttempts.delete(identifier);
    }
  }

  req.cacheKey = identifier;
  next();
}

app.post('/api/login', checkAccountLockout, async (req, res) => {
