      const attempt = failedAttempts.get(req.cacheKey);
      attempt.count++;
      attempt.until = Date.now() + BLOCK_DURATION;
      attempt.timestamp = new Date();
    } else {
      failedAttempts.set(req.cacheKey, {
        count: 1,
        until: Date.now() + BLOCK_DURATION,
        timestamp: new Date()
      });
    }

