// A) Single fetch at start time (faster, single call)
// B) Periodic refresh (auto-reload on changes)
// C) Runtime fetch per request (requires secrets library)

// Option 1: Single fetch at startup - HIGHLY RECOMMENDED
// This pattern is faster and more secure than repeated calls

const fetchAwsSecrets = async () => {
  try {
    const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

    const client = new SecretsManagerClient({ region: process.env.AWS_REGION || 'us-east-1' });
    const secretName = process.env.AWS_SECRET_NAME || 'express-app-production-secrets';

    const response = await client.send(
      new GetSecretValueCommand({ SecretId: secretName })
    );

    let secretString;
    if ('SecretString' in response) {
      secretString = response.SecretString;
    } else {
      // Handle encrypted parsing if Base64-encoded
      const buff = Buffer.from(response.SecretBinary, 'base64');
      secretString = buff.toString('ascii');
    }

    return JSON.parse(secretString);
  } catch (error) {
    // Fallback to environment variables if AWS not available
    console.warn('AWS Secrets Manager failed to load, falling back to .env environment variables:', error.message);
    return null;
  }
};

