async function bootstrap() {
  try {
    secretStore = await fetchSecrets();
    console.log('[INFO] Secrets loaded successfully');
    startServer();
  } catch (error) {
    console.error('[FATAL]', error.message);
    process.exit(1);
  }
}

// 2. Fail fast - don't listen if secrets aren't loaded
function startServer() {
  app.listen(PORT, () => {
    logger.info(`Server listening on port ${PORT}`);
  });
}

// 3. Handle requests safely
app.get('/health', (req, res) => {
  if (!secretStore) {
    return res.status(503).json({ status: 'secrets-loading', error: 'Cannot verify secrets' });
  }

  res.json({
    status: 'ok',
    secretsLoaded: true
  });
});

// Start application
bootstrap();
```

