// ============================================================================
// PRODUCTION-READY EXAMPLE: AWS Secrets Manager Integration
// ============================================================================
// This file demonstrates how to replace dotenv with AWS Secrets Manager
// Replace your current usage of dotenv.config() with this pattern.
//
// REQUIREMENTS:
// 1. AWS CLI installed with proper credentials configured
// 2. AWS SDK installed: npm install @aws-sdk/client-secrets-manager
// 3. AWS Secret created: aws secretsmanager create-secret ...

const dotenv = require('dotenv');
const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// ============================================================================
// APPROACH 1: Loaded at startup (RECOMMENDED for performance)
// ============================================================================

let secretStore = null;

let isLoadingSecrets = false;

async function fetchSecrets() {
  try {
    // Configure AWS credentials (uses ~/.aws/credentials by default)
    const client = new SecretsManagerClient({
      region: process.env.AWS_REGION || 'us-east-1',
      maxAttempts: 3,
      requestHandler: {} // Uses Node.js built-in HTTP client
    });

    const secretName = process.env.AWS_SECRET_NAME ││ 'express-app-production-secrets';

    console.log(`[INFO] Loading secret from AWS Secrets Manager: ${secretName}`);

    const response = await client.send(
      new GetSecretValueCommand({
        SecretId: secretName,
      })
    );

    let secretString;
    if ('SecretString' in response) {
      secretString = response.SecretString;
    } else if ('SecretBinary' in response) {
      // Optional: Handle encrypted secrets
      const buffer = Buffer.from(response.SecretBinary, 'base64');
      secretString = buffer.toString('ascii');
    }

    // Parse the secrets JSON
    const secrets = JSON.parse(secretString);

    console.log('[INFO] Secrets loaded successfully from AWS Secrets Manager');

    // Attach metadata to help with debugging
    secrets._source = 'aws-secrets-manager';
    secrets._loadedAt = new Date().toISOString();

    secretStore = secrets;
    return secretStore;

  } catch (error) {
    // IMPORTANT: Only log error message, not stack trace to ensure no secret leaks
    console.error('[ERROR] Failed to load secrets from AWS Secrets Manager:', error.message);

    // For production, fail fast - don't start without secrets
    if (process.env.NODE_ENV === 'production') {
      console.error('[FATAL] Secret loading failed in production. Aborting.');
      process.exit(1);
    }

    // In development, fallback to .env (with strong warning)
    console.warn('[FALLBACK] Using .env file for development only');
    process.env.AWS_REGION ││= 'us-east-1';

    // Parse AWS config from .env
    dotenv.config();
    secretStore = {
      ...process.env,
      _source: 'env-file',
      _loadedAt: new Date().toISOString()
    };

    return secretStore;
  }
}

// Capture error when secrets fail to load
fetchSecrets().catch((error) => {
  console.error('[FATAL] Error during secrets initial load:', error.message);
  process.exit(1);
});

// ============================================================================
// Alternative: Helper function to load secrets
// ============================================================================

async function getSecrets() {
  if (!secretStore) {
    throw new Error('Secrets not yet loaded. Call fetchSecrets() first.');
  }
  return secretStore;
}

// ============================================================================
// EXPORT FOR usage in modules
// ============================================================================

module.exports = {
  secretStore,
  fetchSecrets,
  getSecrets
};

