# Security Review of app.js

## Executive Summary
The current app.js is a very basic Express application with health and user endpoints. While it doesn't contain many obvious vulnerabilities, it lacks critical security measures common in production environments.

---

## 🔴 CRITICAL VULNERABILITIES

### 1. SQL Injection (No Database Querying)
**Status:** N/A (No SQL database queries present)

**Preventative Measures for Future:**
```javascript
// BAD - Direct SQL query (DO NOT DO THIS)
const query = `SELECT * FROM users WHERE id = ${userId}`;
db.query(query);

// GOOD - Parameterized queries
const query = 'SELECT * FROM users WHERE id = ?';
db.query(query, [userId]);
```

---

### 2. No Authentication or Authorization
**Severity:** CRITICAL
**OWASP Top 10:** A07:2017-A09:2021

**Issue:** All routes are publicly accessible. No authentication mechanism is in place.

**Current State:**
- GET `/health` - Publicly readable (acceptable for health checks)
- GET `/users` - Publicly readable (BAD for user data)

**Recommendation:**
```javascript
// Option 1: JWT Authentication
const jwt = require('jsonwebtoken');
const jwtMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];
  if (!token) {
    return res.status(401).json({ error: 'Access denied' });
  }
  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.userId = decoded.userId;
    next();
  } catch (error) {
    res.status(403).json({ error: 'Invalid token' });
  }
};

// Protect routes
app.get('/users', jwtMiddleware, (req, res) => {
  // Access user-specific data
  res.json({ data: 'Protected data' });
});

// Option 2: API Key Authentication
const apiKeys = new Set(process.env.API_KEYS?.split(',') || []);
const apiKeyMiddleware = (req, res, next) => {
  const apiKey = req.headers['x-api-key'];
  if (!apiKey || !apiKeys.has(apiKey)) {
    return res.status(401).json({ error: 'Invalid API key' });
  }
  next();
};
```

---

### 3. Missing Input Validation
**Severity:** HIGH
**OWASP Top 10:** A05:2021

**Issue:** No validation on request parameters and body data.

**Current State:**
- No body parsing middleware configured
- No parameter validation
- No sanitization

**Recommendation:**
```javascript
const express = require('express');
const validator = require('express-validator');

// Add body parser
app.use(express.json());
app.use(express.urlencoded({ extended: true }));

// Example with input validation
app.get('/users', [
  validator.param('id')
    .isInt({ min: 1 })
    .withMessage('ID must be a positive integer')
    .toInt(),
], (req, res, next) => {
  if (!req.params.id) {
    return res.status(400).json({ error: 'User ID is required' });
  }

  // Validate valid id
  if (req.params.id < 1 || req.params.id > 999) {
    return res.status(400).json({ error: 'ID must be between 1 and 999' });
  }

  // Proceed with request
  res.json({ id: req.params.id, name: 'Alice' });
});

// Example with express-validator middleware
app.post('/create-user', [
  validator.body('name')
    .trim()
    .isLength({ min: 2, max: 50 })
    .escape()
    .withMessage('Name must be 2-50 characters'),
  validator.body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Invalid email address'),
], (req, res) => {
  const errors = validator.validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  res.json({ message: 'User created' });
});

// Implement rate limiting
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later'
});

app.use('/users', limiter);
```

---

### 4. No Security Headers
**Severity:** MEDIUM
**OWASP Top 10:** N/A

**Issue:** No security headers configured.

**Recommendation:**
```javascript
const helmet = require('helmet');

// Set security headers
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "'unsafe-inline'", "'unsafe-eval'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      imgSrc: ["'self'", "data:", "https:"],
      connectSrc: ["'self'"],
      upgradeInsecureRequests: true,
    },
  },
  hsts: {
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true,
  },
  noSniff: true,
  xssFilter: true,
  frameguard: { action: 'deny' },
  referrerPolicy: { policy: 'no-referrer' },
}));
```

---

### 5. CORS Misconfiguration
**Severity:** MEDIUM
**OWASP Top 10:** A01:2021

**Issue:** No CORS configuration listed (currently defaults to allowing all origins).

**Recommendation:**
```javascript
const cors = require('cors');

// Restrict CORS to specific origins
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'https://yourdomain.com',
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
}));
```

---

### 6. Missing Error Handling
**Severity:** MEDIUM
**OWASP Top 10:** N/A

**Issue:** No global error handler for uncaught errors.

**Recommendation:**
```javascript
// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Handle validation errors
  if (err.name === 'ValidationError') {
    return res.status(400).json({ error: err.message });
  }

  // Handle JWT errors
  if (err.name === 'JsonWebTokenError') {
    return res.status(401).json({ error: 'Invalid token' });
  }
  if (err.name === 'TokenExpiredError') {
    return res.status(401).json({ error: 'Token expired' });
  }

  // Handle database errors
  if (err.code) {
    return res.status(500).json({ error: 'Database error' });
  }

  // Default error response
  res.status(500).json({ error: 'Internal server error' });
});
```

---

### 7. Hardcoded Secrets
**Severity:** CRITICAL
**OWASP Top 10:** A07:2017-A09:2021

**Issue:** None present in current code, but be careful adding secrets.

**Recommendation:**
```javascript
// BAD - Using environment variables
const jwtSecret = 'my-super-secret-key-123'; // Should not commit!

// GOOD - Using environment variables (NEVER commit .env)
const jwtSecret = process.env.JWT_SECRET;

// BAD - Logging secrets
console.log('Login successful for user:', user.password);

// GOOD - Don't log sensitive data
console.log('User logged in:', user.username);
```

---

### 8. Authorization Missing for /users
**Severity:** HIGH
**OWASP Top 10:** A07:2017-A09:2021

**Issue:** User data endpoint is completely public.

**Current State:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
