// Update user
app.put('/users/:id', authenticate, async (req, res) => {
  // Authorization check - only update your own data
  if (req.params.id !== req.userId.toString()) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  try {
    // Update logic here
    res.json({ success: true });
