### Implementation Options

#### Option 1: AWS Secrets Manager (Recommended for AWS)

```javascript
// Install
// npm install @aws-sdk/client-secrets-manager dotenv

// app.js
require('dotenv').config();

const { SecretsManagerClient, GetSecretValueCommand } = require('@aws-sdk/client-secrets-manager');

// Initialize manager (DO NOT hardcode region)
const secretsManager = new SecretsManagerClient({
  region: process.env.AWS_REGION || 'us-east-1',
  credentials: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },
});

// Cache secrets to avoid excessive API calls
const secretCache = new Map();

const getSecret = async (secretName, refresh = false) => {
  const cacheKey = `${secretName}_${refresh ? 'forced' : 'cached'}`;

  if (!refresh && secretCache.has(cacheKey)) {
    return secretCache.get(cacheKey);
  }

  try {
    const response = await secretsManager.send(new GetSecretValueCommand({
      SecretId: secretName,
      WithDecryption: true,
    }));

    const secret = response.SecretString || response.SecretBinary.toString('utf8');

    if (!refresh) {
      secretCache.set(cacheKey, secret);
      // Auto-refresh: schedule for 80% of TTL
      if (response.CreatedDate) {
        const ttl = response.SequenceToken ? 2592000 : 86400; // 30 days or 24 hours
        setTimeout(() => getSecret(secretName, true), ttl * 1000);
      }
    }

    return secret;
  } catch (error) {
    console.error(`Failed to fetch secret ${secretName}:`, error);
    throw error;
  }
};

// Example usage
const initApp = async () => {
  try {
    const secrets = {
      database: JSON.parse(await getSecret('prod/db-credentials')),
      jwt: await getSecret('prod/jwt-secret'),
      stripe: await getSecret('prod/stripe-key'),
    };

    // Use secrets to configure application
    const pool = require('pg').Pool({
      user: secrets.database.username,
      host: secrets.database.host,
      database: secrets.database.dbname,
      password: secrets.database.password,
    });

    return pool;
  } catch (error) {
    console.error('Failed to initialize app with secrets:', error);
    process.exit(1);
  }
};

module.exports = { SecretsManagerClient, initApp };

// Start server
initApp().then(pool => {
  app.listen(3000, () => {
    console.log('Server running on port 3000');
  });
});
```

