// app.js - read from Kubernetes Secrets
const { KubeConfig } = require('@kubernetes/client-node');

const kc = new KubeConfig();
kc.loadFromDefault();

const k8sApi = kc.makeApiClient(k8s.CoreV1Api);

const getKubeSecret = async (secretName, namespace = 'default') => {
  const response = await k8sApi.readNamespacedSecret(secretName, namespace);

  // secrets.data keys are base64 encoded
  const secrets = {};
  Object.entries(response.body.data).forEach(([key, value]) => {
    secrets[key] = Buffer.from(value, 'base64').toString('utf8');
  });

  return secrets;
};

